const item = $input.first();
const binary = item.binary || {};
const keys = Object.keys(binary);
const key = keys[0];
let fileName = '';
let ext = '';
if (key && binary[key]) {
  const meta = binary[key];
  fileName = meta.fileName || '';
  ext = String(meta.fileExtension || '').toLowerCase();
}
// Fallback: derive the name/extension from the form field value if binary metadata is missing
if (!ext) {
  const cand = (item.json || {}).Dataset;
  if (typeof cand === 'string') fileName = fileName || cand;
  else if (cand && typeof cand === 'object') fileName = fileName || cand.fileName || cand.filename || cand.name || '';
  ext = String((fileName.split('.').pop() || '')).toLowerCase();
}
return [{ json: { ext, binaryKey: key || 'data', fileName }, binary }];

const items = $input.all();
let rows;
if (items.length && items[0].json && items[0].json.jsonData !== undefined) {
  const jd = items[0].json.jsonData;
  rows = Array.isArray(jd) ? jd : [jd];
} else {
  rows = items.map(i => i.json);
}

// Safety cap so very large files never blow up memory or the model's token limit
const ROW_CAP = 10000;
const totalRows = rows.length;
let analyzed = rows;
let capped = false;
if (totalRows > ROW_CAP) { analyzed = rows.slice(0, ROW_CAP); capped = true; }

const columns = analyzed.length ? Object.keys(analyzed[0]) : [];

// Compute lightweight per-column statistics over the analyzed rows
const stats = {};
for (const col of columns) {
  let nonEmpty = 0, numCount = 0, sum = 0, min = Infinity, max = -Infinity;
  const distinct = new Set();
  for (const r of analyzed) {
    let v = r ? r[col] : undefined;
    if (v === null || v === undefined || v === '') continue;
    nonEmpty++;
    if (distinct.size < 30) distinct.add(String(v));
    const raw = typeof v === 'number' ? v : parseFloat(String(v).replace(/[^0-9.\-]/g, ''));
    if (!isNaN(raw) && String(v).trim() !== '') { numCount++; sum += raw; if (raw < min) min = raw; if (raw > max) max = raw; }
  }
  const isNumeric = numCount > 0 && numCount >= nonEmpty * 0.8;
  stats[col] = isNumeric
    ? { type: 'numeric', nonEmpty, sum: Number(sum.toFixed(2)), avg: numCount ? Number((sum / numCount).toFixed(2)) : null, min: min === Infinity ? null : min, max: max === -Infinity ? null : max }
    : { type: 'text', nonEmpty, distinctSample: Array.from(distinct).slice(0, 15) };
}

const sample = analyzed.slice(0, 50);
const summary = { totalRows, analyzedRows: analyzed.length, capped, columns, stats, sample };
let text = JSON.stringify(summary, null, 2);
const MAX = 45000;
if (text.length > MAX) text = text.slice(0, MAX) + '\n...[truncated]';
return [{ json: { datasetJson: text, rowCount: totalRows, columnCount: columns.length, capped, rows: analyzed } }];

