// Build a clean, Power BI-ready CSV from the parsed dataset rows
const rows = ($('Build Dataset').first().json.rows) || [];
const cols = rows.length ? Object.keys(rows[0]) : [];
function esc(v){ if (v === null || v === undefined) return ''; const s = String(v); return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; }
const lines = [cols.join(',')];
for (const r of rows) { lines.push(cols.map(c => esc(r ? r[c] : '')).join(',')); }
const csv = lines.join('\n');
const base64 = Buffer.from(csv, 'utf8').toString('base64');
return [{ json: { fileName: 'dataset_clean.csv', rowCount: rows.length, columnCount: cols.length }, binary: { data: { data: base64, fileName: 'dataset_clean.csv', mimeType: 'text/csv', fileExtension: 'csv' } } }];
